+#[must_use]
+pub fn is_true(v: &JsValue) -> bool {
+    v.as_boolean() == Some(true)
+}
+
+#[must_use]
+pub fn is_false(v: &JsValue) -> bool {
+    v.as_boolean() == Some(false)
+}
